dashboard.definition:
{
 "title": "Switch Details",
 "description": "One switch: ports, CPU, memory, PoE, traffic, errors, CDP neighbours, MAC table and syslog. Covers Cribl (sw11-13) and gnmic (IOS-XE, NX-OS) telemetry.",
 "inputs": {
  "input_time": {
   "type": "input.timerange",
   "title": "Time range",
   "options": {
    "token": "global_time",
    "defaultValue": "-4h@m,now"
   }
  },
  "input_node": {
   "type": "input.dropdown",
   "title": "Device",
   "dataSources": {
    "primary": "ds_nodes"
   },
   "options": {
    "token": "tk_node",
    "selectFirstSearchResult": true,
    "items": ">frame(label, value) | objects()"
   },
   "context": {
    "label": ">primary | seriesByName(\"node\") | renameSeries(\"label\")",
    "value": ">primary | seriesByName(\"node\") | renameSeries(\"value\")"
   }
  },
  "input_interface": {
   "type": "input.dropdown",
   "title": "Interface",
   "dataSources": {
    "primary": "ds_ifaces"
   },
   "options": {
    "token": "tk_interface",
    "defaultValue": "*",
    "items": ">frame(label, value) | prepend(statics) | objects()"
   },
   "context": {
    "statics": [
     [
      "All"
     ],
     [
      "*"
     ]
    ],
    "label": ">primary | seriesByName(\"interface\") | renameSeries(\"label\")",
    "value": ">primary | seriesByName(\"interface\") | renameSeries(\"value\")"
   }
  }
 },
 "defaults": {
  "dataSources": {
   "ds.search": {
    "options": {
     "queryParameters": {
      "earliest": "$global_time.earliest$",
      "latest": "$global_time.latest$"
     },
     "refresh": "1m",
     "refreshType": "delay"
    }
   }
  }
 },
 "visualizations": {
  "viz_ports": {
   "type": "splunk.table",
   "title": "Ports: green up, dark down, light grey admin down. Click a port to filter.",
   "dataSources": {
    "primary": "ds_ports"
   },
   "options": {
    "count": 20,
    "fontSize": "extraSmall",
    "headerVisibility": "none",
    "table": "> primary | frameWithoutSeriesNames(\"_s01\", \"_s03\", \"_s05\", \"_s07\", \"_s09\", \"_s11\", \"_s13\", \"_s15\", \"_s17\", \"_s19\", \"_s21\", \"_s23\", \"_s25\", \"_s27\", \"_s29\", \"_s31\", \"_s33\", \"_s35\", \"_s37\", \"_s39\", \"_s41\", \"_s43\", \"_s45\", \"_s47\", \"_s49\", \"_s51\", \"_s53\", \"_s55\", \"_s57\", \"_s59\", \"_s61\", \"_s63\", \"_s65\", \"_s67\", \"_s69\", \"_s71\", \"_s73\", \"_s75\", \"_s77\", \"_s79\", \"_s81\", \"_s83\", \"_s85\", \"_s87\", \"_s89\", \"_s91\", \"_s93\", \"_s95\", \"_sU1\", \"_sU3\", \"_sU5\", \"_sU7\")",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(black)"
    },
    "columnFormat": {
