      "match": "up",
      "value": "#53a051"
     },
     {
      "match": "down",
      "value": "#30363d"
     },
     {
      "match": "admin down",
      "value": "#8a929b"
     }
    ],
    "black": [
     "#000000"
    ],
    "textColors": [
