    "visibility": {
     "hideWhenNoData": true
    }
   }
  },
  "viz_cpu": {
   "type": "splunk.markergauge",
   "title": "CPU %",
   "dataSources": {
    "primary": "ds_cpu"
   },
   "options": {
    "orientation": "horizontal",
    "gaugeRanges": [
     {
      "from": 0,
      "to": 70,
      "value": "#53a051"
     },
     {
      "from": 70,
      "to": 90,
      "value": "#f8be34"
     },
     {
      "from": 90,
      "to": 100,
      "value": "#dc4e41"
     }
    ]
   }
  },
  "viz_mem": {
